catalog_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
    g_form.setValue('requested_for', g_user.userID);
    var userSysID = g_user.userID;

    var ga = new GlideAjax('GetManagerSI');

    ga.addParam('sysparm_name', 'getManager');

    ga.addParam('sysparm_sys_id', userSysID);

    ga.getXML(updateManager);
}

function updateManager(response) {

    var answer = response.responseXML.documentElement.getAttribute("answer");

    if (answer) {

              var returneddata = JSON.parse(answer);
              g_form.setValue("manager", returneddata.manager);

      } else {

            alert("Manager Not Found!");

      }

}
